            '**这就是最疼的那部分。**不是从没得到过，而是**得到了、以为稳了，然后当着他的面被拿走**。',
            '',
            '## 三、他在牢里做了什么',
            '',
            '这里有个细节，我觉得特别真实。',
            '',
            '苏轼在狱中一度以为自己要被处死。他给弟弟写诗，写的是：',
            '',
            '> 「是处青山可埋骨，他年夜雨独伤神。」',
            '',
            '青山处处都能埋我，只是以后下雨的夜里，你一个人伤心。',
