            { title: '黄州寒食诗帖（黄州寒食诗二首）', tag: '诗 · 1082 年寒食节 · 天下第三行书', why: '他在黄州写的两首五言诗，后来亲手抄出来，成了书法史上被称为「天下第三行书」的作品（前两名是王羲之《兰亭序》、颜真卿《祭侄文稿》）。\n\n内容是：\n「自我来黄州，已过三寒食。年年欲惜春，春去不容惜。」\n「空庖煮寒菜，破灶烧湿苇。……君门深九重，坟墓在万里。也拟哭途穷，死灰吹不起。」\n\n**这两首要跟《定风波》对着读**：同一年，同一个人，一边写「一蓑烟雨任平生」，一边写「死灰吹不起」。这才是真的苏轼——不是没有低谷，是低谷里还往前挪。' },
            { title: '临江仙·夜饮东坡醒复醉', tag: '词 · 1082 年 · 黄州', why: '「夜饮东坡醒复醉，归来仿佛三更……小舟从此逝，江海寄余生。」宋代人叶梦得的《避暑录话》里记着这么一件事：这首词传出去，黄州太守以为他坐船跑了，赶紧去看，发现他还醉着，鼻息如雷。**这个说法真假不论，但它说明一件事——黄州时期的苏轼，在旁人眼里已经「不像个被贬的人了」。**' }
