            '',
            '翻译一下：官名还挂着，人也被「安置」在这儿，但**你不许上班**，俸禄也砍得几乎不剩。这就是宋朝贬官的规矩——不杀你，也不给你半点权力。',
            '',
            '他到黄州那年四十五岁。二十岁出川时被人抢着要，到这个年纪却被按在一个荒州不许管事——中间隔着的，就是上一集那场大牢。',
