            '- **1082 年七月和十月**，他两次夜里乘船到长江边的赤壁，写出了《**前赤壁赋**》《**后赤壁赋**》和《**念奴娇·赤壁怀古**》——「大江东去，浪淘尽，千古风流人物」。',
