              text: "维元祐八年，岁次癸酉，八月丙午朔，初二日丁未，具位苏轼，谨以家馔酒果，致奠于亡妻同安郡君王氏二十七娘之灵。\n\n呜呼！昔通义君，没不待年。嗣为兄弟，莫如君贤。妇职既修，母仪甚敦。三子如一，爱出于天。从我南行，菽水欣然。汤沐两郡，喜不见颜。我曰归哉，行返丘园。曾不少须，弃我而先。孰迎我门，孰馈我田。已矣奈何，泪尽目干。旅殡国门，我实少恩。惟有同穴，尚蹈此言。呜呼哀哉！",
              note: "**课本坐标：初中教材未收，属于文言祭文。**但这个开头很值得给初中生看一眼：「维元祐八年，岁次癸酉，八月丙午朔，初二日丁未」——一句话里把年月日交代得干干净净，这就是祭文的规矩。\n\n中间那句「**三子如一，爱出于天**」，说的是她待三个儿子一样亲：王弗生的苏迈、她自己生的苏迨和苏过。苏辙在《祭亡嫂王氏文》里也夸过她这一点。\n\n最要紧的是末尾：「**惟有同穴，尚蹈此言。**」——这是当着灵柩许下的愿。八年后他去世，第二年灵柩北运，最后真的与她合葬在郏城（今河南郏县三苏园）。**他这一辈子的话很多，兑现的这一句最实在。**"
