            "## 四、「东坡」这两个字，是他自己造的",
            "",
            "1080 年他到黄州，官衔是「团练副使，本州安置，不得签书公事」——有名无实的空衔，不许管事。一家二十来口要吃饭，他托人向官府申请了城东一块荒废营地，五十亩左右，带家里人去开荒、种麦种豆。",
