            '',
            '据他弟子钱德洪编的《年谱》记载，这孩子出生那天，祖母梦见有神人穿着红玉色的衣服，在云里吹打着乐器，抱着一个娃娃从天而降。祖父听了，给他取名叫「云」，他们家那栋楼从此被叫作「瑞云楼」。',
            '',
            '先别急着信。**这种「生而有异」的记载，是给名人写传记的老套路。**《年谱》里还有个更玄的：说他到五岁还不会说话，一天有个和尚路过，摸着他的头说「好个孩儿，可惜道破」——意思是名字里那个「云」字（云，也有「说」的意思）把这桩天机说破了。祖父一听就懂，改名「守仁」，孩子当场开口。',
            '',
            '**这类说法，当故事听。**但它至少说明：**这一家人从孩子落地起，就认定他不一样。**',
            '',
            '## 二、他十岁那年，父亲成了状元',
