            '',
            '王华就是他父亲。',
            '',
            '状元是什么分量？那是当年全国读书人的头名，直接进翰林院做官。',
            '',
            '王家本来就是读书人家：祖父王伦（号竹轩）藏书不少，脾气宽和，日子过得清淡。但「中了状元」这四个字是另一回事——**它等于告诉这个家：路走对了，照着走就行。**',
            '',
            '第二年，十一岁的他跟着祖父动身进京，去父亲身边读书。',
            '',
            '路上经过镇江金山寺。祖父和客人喝酒，喝得高兴，想题一首诗，一时没写出来。旁边这个十一岁的孩子随口念了一首，满座大惊，又让他再写一首《蔽月山房》：',
            '',
