              note: "**跟这一集什么关系：**这一集第四节讲他练字，出处就是这段自述。「拟形于心」四个字，是全篇的钥匙——**先把字在心里写成，再落到纸上。**他后来讲「心外无理」，讲「知行合一」，用的都是这个路子：先在心上，再在事上。\n\n顺带说一句：他讲这段话时还追问过自己——字写得好看既然不是目的，那到底在学什么？他给的答案是：古人随时随事都在心上用功。**一个十七岁的人练字练到问出这句话，就不只是练字了。**\n\n**课本坐标**：教材未收。这段可以当「练字」话题的引文，但别当成书法理论——**它讲的是心，不是笔。**"
