              "- 今址：南昌老城**广润门**一带，现在的**万寿宫历史文化街区**里重建了「铁柱万寿宫」。",
              "- **要说清楚的**：那是重建的仿古建筑，不是明代那一座。讲的时候说「旧址在这一带」比较稳。",
              "",
              "**三、娄谅是谁**",
              "",
              "- **娄谅**（1422—1491），字克贞，号一斋，江西上饶人。",
              "- 老师是**吴与弼**（号康斋），明代崇仁学派的开山，讲学重在「在日用事上做工夫」，不专在书本上。",
              "- 娄谅自己考过功名、做过教谕一类的小官，中年以后回乡讲学。王阳明见他的那一年，他已经六十多岁，两年后就去世了。",
              "- **一句话记住他**：如果没有娄谅这七个字，王阳明大概会先去做一个诗人，或者一个兵法爱好者。",
              "",
              "**四、官职对照：江西布政司参议是个什么官**",
              "",
              "- 明代一省的最高民政财政机构叫**承宣布政使司**（简称布政司），长官是左、右布政使，从二品。",
              "- 下面设**参政**（从三品）、**参议**（从四品）。",
              "- 打个不精确的比方：**省里分管某一块的副职**——比今天的副省长低，比市长高。**不是小官**，所以这门亲事是正经的门当户对。",
