            "",
            "上一集的最后一句是「祖父去世」。祖父王伦，号竹轩，一辈子没做过什么大官，是个读书、教书、写诗的老先生。他十一岁那年就是跟着这位祖父从余姚去北京的，路上在金山寺还被人考过作诗。",
            "",
            "父亲王华从京师赶回来守丧。按明朝的规矩，官员遇父母之丧要离职回家守制，叫「丁忧」，一般二十七个月。",
            "",
            "所以这三年他不在京城，在余姚。这一段没什么故事——没有婚礼，没有道士，没有边关。只有书。",
