              text: "先生二十一岁，举浙江乡试。是年，为宋儒格物之学。先生始侍龙山公于京师，遍求考亭遗书读之。一日思先儒谓「众物必有表里精粗，一草一木皆涵至理」，官署中多竹，即取竹格之；沉思其理不得，遂遇疾。先生自委圣贤有分，乃随世就辞章之学。",
