              text: "先生二十二岁，试礼部下第。宰相李西涯素爱先生，戏曰：汝今岁不第，来科必作状元，试作《来科状元赋》。先生悬笔立就。诸老惊曰：天才！天才！退有忌者曰：此子若取上第，目中无我辈矣。\n\n先生二十五岁，试礼部下第。同舍有以不第为耻者，先生曰：汝以不得第为耻，吾以不得第动心为耻。",
