              text: "臣闻君仁则臣直。大舜之所以圣，以能隐恶而扬善也。臣迩者窃见陛下以南京户科给事中戴铣等上言时事，特敕锦衣卫差官校拿解赴京。臣不知所言之当理与否，意其间必有触冒忌讳，上干雷霆之怒者。\n\n但铣等职居谏司，以言为责；其言而善，自宜嘉纳施行；如其未善，亦宜包容隐覆，以开忠谠之路。乃今赫然下令，远事拘囚，在陛下之心，不过少示惩创，使其后日不敢轻率妄有论列，非果有意怒绝之也。下民无知，妄生疑惧，臣切惜之！\n\n今在廷之臣，莫不以此举为非宜，然而莫敢为陛下言者，岂其无忧国爱君之心哉？惧陛下复以罪铣等者罪之，则非惟无补于国事，而徒足以增陛下之过举耳。然则自是而后，虽有上关宗社危疑不制之事，陛下孰从而闻之？陛下聪明超绝，苟念及此，宁不寒心！\n\n况今天时冻冱，万一差去官校督束过严，铣等在道或致失所，遂填沟壑，使陛下有杀谏臣之名，兴群臣纷纷之议，其时陛下必将追咎左右莫有言者，则既晚矣。\n\n伏愿陛下追收前旨，使铣等仍旧供职；扩大公无我之仁，明改过不吝之勇；圣德昭布远迩，人民胥悦，岂不休哉！",
