              "**二、石墎是什么**",
              "",
              "- 「墎」同「椁」，外棺。**石墎＝石头做的外棺**，也就是俗称的石棺。",
              "- 关于他做石棺这件事，有两种读法：一种说他准备死在这里；一种说他用「躺进棺材」的办法逼自己把生死这一念看透。**《年谱》原文「吾惟俟命而已」偏向后者**——「俟命」是等天命，不是寻死。",
              "- 一个旁证：他后来在《瘗旅文》里写「吾与尔犹彼也」，对陌生人的死都能这么平静，说明他这两年确实把「死」想透了。",
              "",
              "**三、《明夷》卦是什么意思**",
              "",
              "- 《周易》第三十六卦，**离下坤上**：离为火为明，坤为地为顺。明在地下，叫「明夷」——光明受伤。",
              "- 卦辞：「明夷，利艰贞。」**在艰难中守正，才有利。**",
              "- 《彖传》：「内文明而外柔顺，以蒙大难，文王以之。」——里面明白，外面柔顺，靠这个渡过大的灾难。**据说周文王被囚羑里时就是这个卦象。**",
              "- 道士给他这一卦，意思很明确：**现在不是出头的时候，把光收进去。**",
              "",
              "**四、他在贵州待了多久**",
