              text: "即日已抵龙南，明日入巢，四路兵皆已如期并进，贼有必破之势。某向在横水，尝寄书仕德云：「破山中贼易，破心中贼难。」区区剪除鼠窃，何足为异？若诸贤扫荡心腹之寇，以收廓清平定之功，此诚大丈夫不世之伟绩。",
              note: "**跟这一集什么关系：**这是全集里最短、也最重的一封信。写它的时候他正在往山里走，明天就要开打，可他关心的不是这一仗。\n\n**注意「区区」两个字。** 平三股盘了几十年的势力，朝廷记功、加官，他自己用了「区区剪除鼠窃」六个字。**这不是自谦，是他真的这么排的序。**\n\n**「心腹之寇」四个字用得准。** 山贼在山里，心贼在心里——一个你能画地图，一个你连它在哪儿都不知道。**这就是他后来「致良知」的入口：难的不是打败谁，是看见自己。**\n\n**收信人是谁**：杨仕德、薛侃，都是他在赣州时期的学生。薛侃后来在赣州刻了《传习录》，是心学传下去的关键一环。\n\n**课本坐标**：教材未收。讲「用兵」可与统编版**九年级下册**《曹刿论战》对读——曹刿也是以一个非职业军人的身份论战，讲的是「肉食者鄙，未能远谋」。**两篇合起来是一个很好的作文材料：赢的不是力气，是看得清。**",
