              text: "咨尔民，昔人有言：「蓬生麻中，不扶而直；白沙在泥，不染而黑。」民俗之善恶，岂不由于积习使然哉！",
              note: "**跟这一集什么关系：**打完仗他做的第一件事，不是修祠堂、不是立碑，是**给老百姓订一份约**。这份约规定每乡推举约长、约副，定期聚会，讲道理、记善恶、调解纠纷。\n\n**开头这三句极漂亮。** 「蓬生麻中，不扶而直」——蓬草长在麻地里，不用扶它自己就直了；「白沙在泥，不染而黑」——白沙掉进泥里，不用染它自己就黑了。**他要说的不是人坏，是环境在替人做决定。**\n\n**这跟他平乱的经验是通的**：一个村子替山贼藏人，多半不是因为坏，是因为怕，也因为没人替它撑腰。**所以他把「撑腰」这件事制度化**——约长就是这么个角色。\n\n**一个提醒**：乡约不是他首创，北宋《吕氏乡约》早有；他的功劳是**把它在战后的南赣真的推行下去**，而且加了强制性的奖惩。\n\n**课本坐标**：教材未收。思想上可与统编版**八年级下册**《〈礼记〉二则·大道之行也》对读——「讲信修睦」「不独亲其亲」讲的是理想，这份乡约讲的是**怎么在一个刚打完仗的县里，把这句话变成每月的例会**。",
