            '他父亲叫毛顺生。这个人一辈子就干一件事——**从穷里往外爬**。当过兵，回来种田、贩米、做小生意，一笔一笔地置田。到后来，家里从贫农变成了当地小有余粮的人家。',
            '',
            '毛顺生对这个长子的规划很明确：**识字、记账、管家业**。会打算盘，能写状子，将来把这份家业接过去。',
