              note: '这一集「从几百人到几万人」，最后落在这首诗上。**课本坐标：统编版六年级上册第二单元第 5 课《七律·长征》**——学生小学就背过，正好可以拿来串。\n\n八句诗里几乎全是地名：五岭、乌蒙、金沙江、大渡河、岷山。**每一个地名背后都是一次死里逃生**：四渡赤水、巧渡金沙江、飞夺泸定桥、翻雪山。\n\n注意「暖」和「寒」两个字对着看：金沙江是巧渡，水拍云崖，心里是暖的；泸定桥是大渡河上的铁索桥，脚下是空的，那是彻骨的寒。**八句诗，差不多每一句都是一条命。**'
