            '一九二八年十月，他写下《**中国的红色政权为什么能够存在？**》。他不是喊口号，他一条一条地数条件：中国不是铁板一块，而是被好几个帝国主义国家分别控制的半殖民地，**各派军阀背后各有靠山、自己就得不停地打**——这就是红色政权能夹在中间活下来的缝隙；此外，湘、鄂、赣、粤这些省份经历过大革命、农民运动有底子，全国革命形势还在往前走，手里又有一支正式的红军。',
