              note: '**这一集的那篇文章，就是它。**注意它一上来不喊口号，先跟你算时间：分三个阶段，然后一段一段说这个阶段该干什么。\n\n**课本坐标：《论持久战》不在语文课本里**；它在**统编版历史八年级上册「中华民族的抗日战争」**那部分会被提到。对语文老师来说，它最大的用处是——**讲议论文时拿它当范例：先驳两种说法，再立自己的判断，然后分阶段落实。**'
