              text: '人总是要死的，但死的意义有不同。中国古时候有个文学家叫做司马迁的说过：「人固有一死，或重于泰山，或轻于鸿毛。」为人民利益而死，就比泰山还重；替法西斯卖力，替剥削人民和压迫人民的人去死，就比鸿毛还轻。\n\n因为我们是为人民服务的，所以，我们如果有缺点，就不怕别人批评指出。不管是什么人，谁向我们指出都行。只要你说得对，我们就改正。',
