              note: "**课本坐标：这首不在统编初中语文教材里**；但**统编版八年级上册第一单元「消息二则」**（《我三十万大军胜利南渡长江》《人民解放军百万大军横渡长江》）写的就是同一件事——同一场渡江，一处写成新闻，一处写成诗。讲新闻单元时把这两样摆在一起，学生能看见「同一件事、两种文体」到底差在哪儿。\n\n「**宜将剩勇追穷寇，不可沽名学霸王**」是全篇的关键一句：项羽当年在鸿门宴上放过刘邦，图个虚名，最后输掉了全部——**他是拿项羽提醒自己：这个时候不能停。**\n\n最后一句「人间正道是沧桑」——世界本来就是在变的，而变的方向，就是正道。"
