            '',
            '第二件，给他认了个干娘——不是人，是韶山滴水洞那边的一块大石头。乡下人信这个：孩子命硬不硬，得靠神明护着。这块石头后来被叫作「石干娘」，他也就多了个小名：**石三伢子**。',
