            "**一个农村妇女，七个孩子，埋了四个。**这是理解她的第一个背景。",
            "## 二、她不识字，但有一套道理",
            "她信佛。不是「求菩萨保佑儿子当官」那种信，是过日子式的：初一十五吃斋，家里供着香火，见庙就拜。",
            "据他后来对斯诺说：母亲是个虔诚的佛教徒，也向孩子灌输佛教信仰；他小时候受过影响，后来完全不信了。",
            "但宗教在她身上落成的不是仪式，是**一种对弱者的本能**。",
            "有件事他记了一辈子：荒年里讨饭的人上门，母亲会量米给他们。父亲不同意——粮是一笔笔算出来的，给人就是亏。她就背着给。",
            "**父亲讲「算清楚」，母亲讲「该给」。**这两样东西后来都长在他身上：算阶级人数、算兵力对比时他狠得下心，可最动人的那几篇讲的都是「该给」。",
            "## 三、这个家里有两个「党」",
            "1936 年他对斯诺讲过一段很有名的话：",
            "> 我家分成两党。一党是我父亲，是执政党。反对党由我、母亲、弟弟组成，有时连雇工也包括在内。",
            "还有一句常被漏掉：",
            "> 但反对党内部也有分歧。母亲主张一种间接打击的政策。凡是不赞成我父亲的事，她都不同意直接反对，而是用迂回的方式去做。",
            "「间接打击的政策」——这几个字是一个成年政治家说出来的，说的是他自己的妈。",
