            "## 四、她把大儿子送回了娘家",
            "还有个安排，比念佛和施米更实际。",
            "他幼年有一大半时间不在韶山冲，在唐家圫外婆家——从两岁起断断续续住到八岁。原因说法不一，但**结果很重要**。",
            "外婆家有个八舅，叫文正莹（又作文玉钦），在家开馆授徒。他在舅舅的学堂里旁听，跟着念蒙书。**他的第一个「学校」不在自己家，在母亲娘家。**",
            "分量在这儿：这个孩子在「算账的家」之外，还有一个「读书的家」。父亲那条路是识字、会算、接家业；舅舅那边露出的是另一条路——读书可以不为算账。",
            "## 五、1919 年，那半年",
            "1919 年春母亲病重。她长年有病，什么病记载不一（有说淋巴结核）。他把母亲接到长沙诊治。",
            "就在这段时间，三个儿子和母亲拍了一张合影。**这是文七妹留下的唯一一张照片。**",
            "病稍好，她坚持回韶山——乡下人的道理：不能死在外头。1919 年 10 月 5 日病逝于韶山。五十三岁（虚岁；按实岁是五十二）。",
            "他在长沙，接到二弟的信连夜往回赶。**晚了一步。**",
            "## 六、他写下的那篇东西",
