            "> 吾母高风，首推博爱。远近亲疏，一皆覆载。",
            "「博爱」这两个字用在一个湖南农村妇女身上是很重的词。他写的不是「慈」，是「博爱」——对远近亲疏都一样。",
            "他还写了两副挽联。长的一副：",
            "> 疾革尚呼儿，无限关怀，万端遗恨皆须补；",
            "> 长生新学佛，不能住世，一掬慈容何处寻。",
            "上联写母亲临终还在喊儿子；下联写她学佛求长生还是留不住。另一副短些：**春风南岸留晖远，秋雨韶山洒泪多。**",
            "三个半月后，1920 年 1 月父亲也去世了。他那时在北京忙「驱张」，也没能赶回来。二十六岁那年，他没有家了。",
            "## 七、母亲给他留下了什么",
