              text: "吾母高风，首推博爱。\n远近亲疏，一皆覆载。\n恺恻慈祥，感动庶汇。\n爱力所及，原本真诚。\n不作诳言，不存欺心。\n\n（全文四百余字，此处取论母德的开头一段）",
              note: "**跟这一集什么关系：**这一集第六节讲的就是它。母亲去世时他二十六岁，此前写的多是笔记、批注、短文，这是他留下来的**第一篇长篇韵文**——四字一句，一路写下来，写的是一个农村妇女的一生。\n\n**课本坐标：教材未收。**统编版初中语文收的毛泽东作品是《纪念白求恩》（七上）这类文章，诗词方面《七律·长征》在六年级上册、《沁园春·雪》在九年级上册，都没有这一篇。\n\n讲给学生听，重点不在「这是伟人写的」，在**他选了哪些词**：「博爱」「覆载」都是大词——「覆载」是天地覆盖承载万物的意思。他用写天地的词写一个文盲农妇，这不是拔高，是他真觉得母亲配得上。"
