              text: "孩儿立志出乡关，学不成名誓不还。\n埋骨何须桑梓地，人生无处不青山。",
              note: "**跟这一集什么关系：**第三节讲的就是它。这是整条线里第一件「他自己的文字」——前面五集他都是被讲的人，从这一首开始，他学着自己说话。\n\n两个字的改动（男儿→孩儿、死不还→誓不还）是这一集最实用的一处：**同一件事，换个说法，重量就不一样。**\n\n**课本坐标**：统编版初中语文、高中语文均未收这一首。统编版**高中语文必修上册第一单元**收了他的《沁园春·长沙》，可作「青年言志」的对照读——一个是十六岁出门前留给父亲的，一个是三十二岁站在橘子洲头的。\n\n**存疑**：改诗这件事是确定的（原作是日本明治年间的诗，西乡隆盛与僧人月性两说并存）；「抄在纸上夹进账簿」这个细节出自《毛泽东年谱》一系的记载，具体形式各家说法不一。"
