              text: "（原文已佚。以下是 1936 年他在陕北窑洞里对斯诺回忆的大意，非逐字引文。）\n\n我写了一篇文章贴在学校的墙上。这是我第一次发表政见，思想还有些糊涂——我还没有放弃对康有为、梁启超的钦佩。所以我主张：孙中山当新政府的总统，康有为当国务总理，梁启超当外交部长。",
