            "",
            "## 五、省立一中：一篇作文",
            "",
            "下一所是湖南全省高等中学校——后来改名省立第一中学，就是今天的长沙市一中。",
            "",
            "又是第一名。",
            "",
            "在这里他写了一篇作文，题目叫《商鞅徙木立信论》。",
            "",
            "商鞅变法之前，为了让人相信官府说话算话，在国都南门立了一根三丈长的木头，说谁能搬到北门就赏十金。没人动。加到五十金，有人搬了，当场给钱。",
