              "- **江亢虎**（1883—1954）：江西上饶人，1911 年 11 月在上海组织「中国社会党」，办《社会星》等刊物，大讲「社会主义」。",
              "- 他讲的那一套，核心是**社会改良**：遗产归公、教育普及、男女平权之类，靠议会与教育慢慢改，**不主张阶级斗争，也不主张暴力革命**。",
              "- 所以他 1912 年在《湘汉新闻》上读到的「社会主义」，跟后来《共产党宣言》里那一套不是一回事。**这个区别很重要：一个人第一次接触一个名词时，接住的往往只是这个词的影子。**",
