              note: "**跟这一集什么关系：**这就是这一集的正文本。**一百来字，四个动作：自报家门、划出标准、说明求法、借《诗经》收尾。**\n\n**它最像什么**：像一张招聘启事。**「皆吾之所求也」——他把话说得很直：我是在挑人。**二十二岁的人敢这么写，是因为他真觉得自己要找的是一件大事。\n\n**关于原文**：各家转录略有出入（「能耐艰苦劳顿」也有作「能耐艰辛劳顿」的），**通行本即上面这一百来字**，讲的时候不必逐字抠。\n\n**课本坐标**：教材未收。但它引的两句都出自《诗经》——《小雅·伐木》「嘤其鸣矣，求其友声」，《小雅·正月》「将伯助予」。统编版**八年级下册**第三单元有《诗经》二首（《关雎》《蒹葭》），学生学过「赋比兴」——**这里正是「兴」：先写鸟叫，再说我想找朋友。**"
