              text: "我住在一个叫做三眼井的地方，同另外七个人住在一间小屋子里。我们大家都睡到炕上的时候，挤得几乎透不过气来。每逢我要翻身，得先同两旁的人打招呼。\n\n李大钊给了我图书馆助理员的工作，工资不低，每月有八块钱。\n\n我的职位低微，大家都不愿同我来往。我的一项任务是登记来图书馆读报的人的姓名，可是对他们大多数人来说，我这个人是不存在的。他们都是在忙别的事情的人……没有时间听一个图书馆助理员说南方话。\n\n（据董乐山译本，个别字句各家转译略有出入）",
