              note: "**跟这一集什么关系：**这是他自己办的第一份报、自己写的第一篇发刊词。二十六岁，第一次站在「主编」这个位置上说话。\n\n**注意开头的问法。** 他不问「什么主义最正确」，问「什么问题最大」。**这是一个先把问题排顺序的人。** 后来他一辈子都是这么开头的：先问「谁是我们的敌人，谁是我们的朋友」，先问「中国向何处去」。\n\n**那一串「不要怕」值得念出声。** 天、鬼、死人、官僚、军阀、资本家——从最虚的排到最实的。**排在最前面的是「天」和「鬼」，最后才是「资本家」**：他知道老百姓心里先怕的是什么。\n\n**课本坐标**：教材未收。可作为统编版**八年级上册**名著导读《红星照耀中国》的补充材料——那本书讲的是他后来的事，这段文字能让人看见「后来」之前的起点。"
