              "",
              "**一、文七妹是谁**",
              "",
              "- 文素勤（1867—1919），娘家在**湘乡县唐家圫**（今属韶山市），在同族姐妹中排行第七，所以叫「文七妹」。",
              "- 十八岁嫁到韶山冲上屋场，丈夫毛顺生。**她信佛，常年吃「观音斋」**（每逢观音生日等日子吃素）。",
              "- 她生了七胎，成活三个儿子：泽东、泽民（泽民原名泽民，字润莲）、泽覃。**另两女两男均夭折。**",
              "- 因为她身体不好、孩子又难带，毛泽东幼年有很长一段时间寄养在湘乡唐家圫的外婆家——**这也是他后来能去湘乡东山读高小的原因**（靠的是外婆家在湘乡的关系，见第 6 集）。",
              "",
              "**二、修业小学在哪儿**",
              "",
