              "- 1919 年 4 月他到该校任**历史教员**，是周世钊介绍的。**工资很低**，但管住，且离第一师范近，方便往来。",
              "- **注意别混**：同年秋天他还在**修业小学**住，同时主编《湘江评论》，还在长沙各家报纸写稿——**这三件事的地址其实是同一个院子。**",
              "",
              "**三、张敬尧是谁**",
              "",
              "- 张敬尧（1881—1933），安徽霍邱人，**皖系军阀**。1918 年 3 月率军入湘，任湖南督军兼省长，到 1920 年 6 月被驱走。",
              "- 湖南人叫他「**张毒**」。他在湘三年，苛捐、种烟（鸦片）、滥发纸币，被列为「驱张」三大罪状。",
              "- **一个数字口径**：驱张运动里常引「张敬尧在湘三年搜刮银元两千余万」，这个数字出自当时湖南各界的呈文，**属当时舆论的估算，不是账本上的数**——引用时说「据当时湖南各界呈文」比较稳。",
              "",
              "**四、三处要小心的时间口径**",
              "",
              "- **母亲的忌日**：**1919 年 10 月 5 日**（农历八月十二）。有材料只写「10 月」，写具体日子的以 10 月 5 日为准。",
              "- **《祭母文》的写作时间**：写在丧礼期间（10 月上中旬）。**注意它不是事后追写的回忆文章，是当场念的。**",
              "- **《湘江评论》的创刊日**：**1919 年 7 月 14 日**。有材料写「7 月」，是省称。",
              "",
              "**五、一个容易想错的地方**",
              "",
              "- 很多人以为他 1919 年就已经是「马克思主义者」。**不是。** 这一年他读的主要还是《新青年》、实验主义、无政府主义、新村主义这些；**他系统接触《共产党宣言》要到 1920 年**（下一卷的事）。",
              "- **但这不妨碍他写《民众的大联合》。** 这篇文章的底子是湖南这几年的实感，不是书本。**顺序是：先看见，再找理论。** 这一点对他后来的路影响极大。",
