          next: "《湘江评论》被封不是结束。1919 年 11 月，长沙一个叫赵五贞的姑娘在花轿里割喉自尽，他连着写了九篇文章；12 月，他带着学生上街烧日货、办罢课，把督军张敬尧赶出了湖南。下一集讲这场「驱张」——一个二十六岁的教员，手里没有一兵一卒，怎么把一个军阀赶走。"
